use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut shipments = BTreeMap::new();

    for _ in 0..n {
        let (id, state) = lines.next().unwrap().split_once('|').unwrap();
        shipments.insert(id.to_string(), state.to_string());
    }

    let m: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut invalid = 0;
    for _ in 0..m {
        let (id, action) = lines.next().unwrap().split_once('|').unwrap();
        if let Some(state) = shipments.get_mut(id) {
            let next = match (state.as_str(), action) {
                ("created", "pack") => Some("packed"),
                ("packed", "ship") => Some("shipped"),
                ("shipped", "deliver") => Some("delivered"),
                ("created", "cancel") | ("packed", "cancel") => Some("cancelled"),
                _ => None,
            };
            if let Some(next_state) = next {
                *state = next_state.to_string();
            } else {
                invalid += 1;
            }
        } else {
            invalid += 1;
        }
    }

    let states = shipments
        .iter()
        .map(|(id, state)| format!("{id}:{state}"))
        .collect::<Vec<_>>()
        .join(",");
    println!("{states}|invalid={invalid}");
}

source_texts.wildcard_policy_extension:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut policies = Vec::new();
    for _ in 0..n {
        let mut parts = lines.next().unwrap().split('|');
        policies.push((
            parts.next().unwrap().to_string(),
            parts.next().unwrap().to_string(),
            parts.next().unwrap().to_string(),
        ));
    }
    let m: usize = lines.next().unwrap().parse().unwrap();
    let mut allowed = 0;
    let mut denied = 0;
    for _ in 0..m {
        let line = lines.next().unwrap();
        let mut parts = line.split('|');
        let user = parts.next().unwrap();
        let role = parts.next().unwrap();
        let resource = parts.next().unwrap();
        let action = parts.next().unwrap();
        let matches = |policy: &str, value: &str| policy == "*" || policy == value;
        if policies.iter().any(|(policy_role, policy_resource, policy_action)| {
            matches(policy_role, role)
                && matches(policy_resource, resource)
                && matches(policy_action, action)
        }) {
            allowed += 1;
            println!("{user}:allow");
        } else {
            denied += 1;
            println!("{user}:deny");
        }
    }
    println!("allowed={allowed},denied={denied}");
}

