use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut policies = Vec::new();
    for _ in 0..n {
        let parts: Vec<&str> = lines.next().unwrap().split('|').collect();
        policies.push((parts[0].to_string(), parts[1].to_string(), parts[2].to_string()));
    }
    let m: usize = lines.next().unwrap().parse().unwrap();
    let mut allowed = 0;
    let mut denied = 0;
    for _ in 0..m {
        let line = lines.next().unwrap();
        let parts: Vec<&str> = line.split('|').collect();
        let user = parts[0];
        let request = (&parts[1], &parts[2], &parts[3]);
        let matches = policies.iter().any(|policy| {
            (policy.0 == "*" || policy.0 == *request.0)
                && (policy.1 == "*" || policy.1 == *request.1)
                && (policy.2 == "*" || policy.2 == *request.2)
        });
        if matches {
            allowed += 1;
            println!("{user}:allow");
        } else {
            denied += 1;
            println!("{user}:deny");
        }
    }
    println!("allowed={allowed},denied={denied}");
}

