source_texts.invoice_net_extension:
use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let customer = lines.next().unwrap_or("");
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut categories: BTreeMap<String, u128> = BTreeMap::new();
    let mut subtotal: u128 = 0;
    for _ in 0..n {
        let parts: Vec<&str> = lines.next().unwrap().split('|').collect();
        let quantity: u128 = parts[1].parse().unwrap();
        let price: u128 = parts[2].parse().unwrap();
        let amount = quantity * price;
        subtotal += amount;
        *categories.entry(parts[0].to_string()).or_default() += amount;
    }
    let totals = categories.iter().map(|(category, amount)| format!("{category}:{amount}")).collect::<Vec<_>>().join(",");
    let discount = if subtotal >= 2000 { subtotal / 10 } else { 0 };
    let net = subtotal - discount;
    println!("{customer}|{subtotal}|{totals}|discount={discount}|net={net}");
}

