use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut shipments = BTreeMap::new();

    for _ in 0..n {
        let (id, state) = lines.next().unwrap().split_once('|').unwrap();
        shipments.insert(id.to_string(), state.to_string());
    }

    let m: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut invalid = 0;
    for _ in 0..m {
        let (id, action) = lines.next().unwrap().split_once('|').unwrap();
        if let Some(state) = shipments.get_mut(id) {
            let next = match (state.as_str(), action) {
                ("created", "pack") => Some("packed"),
                ("packed", "ship") => Some("shipped"),
                ("shipped", "deliver") => Some("delivered"),
                ("created" | "packed", "cancel") => Some("cancelled"),
                _ => None,
            };
            if let Some(next_state) = next {
                *state = next_state.to_string();
            } else {
                invalid += 1;
            }
        } else {
            invalid += 1;
        }
    }

    let states = shipments
        .iter()
        .map(|(id, state)| format!("{id}:{state}"))
        .collect::<Vec<_>>()
        .join(",");
    println!("{states}|invalid={invalid}");
}

source_texts.notes_index_extension:
use std::fs;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let title = lines.next().unwrap_or("");
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    let notes: Vec<&str> = (0..n).map(|_| lines.next().unwrap_or("")).collect();
    let mut contents = String::new();
    contents.push_str(title);
    contents.push('\n');
    for note in &notes {
        contents.push_str(note);
        contents.push('\n');
    }
    fs::write("file_backed_notes.txt", contents).unwrap();
    let saved = fs::read_to_string("file_backed_notes.txt").unwrap();
    let mut saved_lines = saved.lines();
    let saved_title = saved_lines.next().unwrap_or("");
    let saved_notes: Vec<&str> = saved_lines.take(n).collect();
    let mut index = String::new();
    for (position, note) in saved_notes.iter().enumerate() {
        if !note.is_empty() {
            index.push_str(&format!("{}|{}\n", position + 1, note));
        }
    }
    fs::write("file_backed_notes_index.txt", index).unwrap();
    let nonempty = saved_notes.iter().filter(|note| !note.is_empty()).count();
    let characters: usize = saved_notes.iter().map(|note| note.len()).sum();
    println!("{}|{}|{}|{}", saved_title, n, nonempty, characters);
}

source_texts.invoice_net_extension:
use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let customer = lines.next().unwrap_or("");
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut categories: BTreeMap<String, u128> = BTreeMap::new();
    let mut subtotal: u128 = 0;
    for _ in 0..n {
        let parts: Vec<&str> = lines.next().unwrap().split('|').collect();
        let quantity: u128 = parts[1].parse().unwrap();
        let price: u128 = parts[2].parse().unwrap();
        let amount = quantity * price;
        subtotal += amount;
        *categories.entry(parts[0].to_string()).or_default() += amount;
    }
    let totals = categories.iter().map(|(category, amount)| format!("{category}:{amount}")).collect::<Vec<_>>().join(",");
    let discount = if subtotal >= 2000 { subtotal / 10 } else { 0 };
    let net = subtotal - discount;
    println!("{customer}|{subtotal}|{totals}|discount={discount}|net={net}");
}

source_texts.wildcard_policy_extension:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut policies = Vec::new();
    for _ in 0..n {
        let parts: Vec<&str> = lines.next().unwrap().split('|').collect();
        policies.push((
            parts[0].to_string(),
            parts[1].to_string(),
            parts[2].to_string(),
        ));
    }
    let m: usize = lines.next().unwrap().parse().unwrap();
    let mut allowed = 0;
    let mut denied = 0;
    for _ in 0..m {
        let parts: Vec<&str> = lines.next().unwrap().split('|').collect();
        let user = parts[0];
        let request = (&parts[1], &parts[2], &parts[3]);
        let matches = policies.iter().any(|policy| {
            (policy.0 == "*" || policy.0 == *request.0)
                && (policy.1 == "*" || policy.1 == *request.1)
                && (policy.2 == "*" || policy.2 == *request.2)
        });
        if matches {
            allowed += 1;
            println!("{user}:allow");
        } else {
            denied += 1;
            println!("{user}:deny");
        }
    }
    println!("allowed={allowed},denied={denied}");
}

