fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut policies = Vec::new();
    for _ in 0..n {
        let mut parts = lines.next().unwrap().split('|');
        policies.push((
            parts.next().unwrap().to_string(),
            parts.next().unwrap().to_string(),
            parts.next().unwrap().to_string(),
        ));
    }
    let m: usize = lines.next().unwrap().parse().unwrap();
    let mut allowed = 0;
    let mut denied = 0;
    for _ in 0..m {
        let line = lines.next().unwrap();
        let mut parts = line.split('|');
        let user = parts.next().unwrap();
        let role = parts.next().unwrap();
        let resource = parts.next().unwrap();
        let action = parts.next().unwrap();
        let matches = policies.iter().any(|(policy_role, policy_resource, policy_action)| {
            (policy_role == "*" || policy_role == role)
                && (policy_resource == "*" || policy_resource == resource)
                && (policy_action == "*" || policy_action == action)
        });
        if matches {
            allowed += 1;
            println!("{user}:allow");
        } else {
            denied += 1;
            println!("{user}:deny");
        }
    }
    println!("allowed={allowed},denied={denied}");
}

